import java.text.Normalizer;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The filters supported by the customer backend.
 *
 * @param name     whitespace-separated terms to match against first or last name
 * @param statuses accepted statuses; an empty set accepts every status
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");
    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null || statuses.isEmpty()
                ? Set.of()
                : Set.copyOf(EnumSet.copyOf(statuses));
    }

    public static CustomerFilter empty() {
        return new CustomerFilter("", Set.of());
    }

    /** Returns whether the customer satisfies both parts of this filter. */
    public boolean matches(Customer customer) {
        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
            return false;
        }

        String normalizedFilter = normalize(name).strip();
        if (normalizedFilter.isEmpty()) {
            return true;
        }

        String firstName = normalize(customer.firstName());
        String lastName = normalize(customer.lastName());
        return WHITESPACE.splitAsStream(normalizedFilter)
                .allMatch(term -> firstName.contains(term) || lastName.contains(term));
    }

    /** Returns whether this filter has no effective name or status restriction. */
    public boolean isEmpty() {
        return name.isBlank() && statuses.isEmpty();
    }

    private static String normalize(String value) {
        return DIACRITICS.matcher(Normalizer.normalize(value, Normalizer.Form.NFD))
                .replaceAll("")
                .toLowerCase(Locale.ROOT);
    }
}
