+package com.example.customers;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import com.example.Application;
+import com.example.customers.domain.QueryLog;
+import com.microsoft.playwright.Locator;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.MultiSelectComboBoxElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(classes = Application.class,
+        webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class CustomerListViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Autowired
+    private QueryLog queryLog;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Test
+    void typingIsDebouncedAndReplacesTheCurrentUrl() {
+        page.locator("vaadin-grid").waitFor();
+        page.waitForTimeout(500);
+        int initialHistoryLength = ((Number) page.evaluate("history.length")).intValue();
+        queryLog.clear();
+
+        TextFieldElement name = new TextFieldElement(page.locator("vaadin-text-field"));
+        name.getInputLocator().pressSequentially("josephine",
+                new Locator.PressSequentiallyOptions().setDelay(25));
+
+        page.waitForFunction("() => window.location.search === '?name=josephine'");
+        assertEquals(1, queryLog.countQueries().size(),
+                "A burst of typing should produce one filtered count query");
+        assertEquals(initialHistoryLength, ((Number) page.evaluate("history.length")).intValue());
+
+        MultiSelectComboBoxElement statuses = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        statuses.selectItems("CLOSED", "ACTIVE");
+        page.waitForFunction("() => window.location.search === "
+                + "'?name=josephine&status=ACTIVE,CLOSED'");
+        assertEquals(initialHistoryLength, ((Number) page.evaluate("history.length")).intValue());
+
+        name.clear();
+        statuses.deselectItems("CLOSED", "ACTIVE");
+        page.waitForFunction("() => window.location.search === ''");
+        assertEquals(initialHistoryLength, ((Number) page.evaluate("history.length")).intValue());
+    }
+
+    @Test
+    void openingAFilteredUrlPopulatesTheControls() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForFunction("() => document.querySelector('vaadin-text-field')?.value === 'vir'");
+
+        TextFieldElement name = new TextFieldElement(page.locator("vaadin-text-field"));
+        MultiSelectComboBoxElement statuses = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        assertEquals("vir", name.getValue());
+        statuses.assertSelectedItems("ACTIVE", "CLOSED");
+    }
+}
